function setupDragging() {
  const ow = document.getElementById('ow');
  ow.onmousedown = e => {
      if (currentMode !== 'offset') return;
      const activeStudents = loadedStudents.filter(x => x.active);
      if(activeStudents.length === 0) return;
      isDragging = true;
      startX = e.clientX; startY = e.clientY;
      activeStudents.forEach(s => {
          s.initDx = s.dx || 0;
          s.initDy = s.dy || 0;
      });
  };
  window.onmousemove = e => {
      if(!isDragging) return;
      const rect = CS.getBoundingClientRect();
      const scaleX = cW / rect.width;
      const scaleY = cH / rect.height;
      const deltaX = (e.clientX - startX) * scaleX;
      const deltaY = (e.clientY - startY) * scaleY;
      
      const activeStudents = loadedStudents.filter(x => x.active);
      activeStudents.forEach(s => {
          s.dx = s.initDx + deltaX;
          s.dy = s.initDy + deltaY;
      });
      drawAll();
  };
  window.onmouseup = e => {
      if(!isDragging) return;
      isDragging = false;
      const activeStudents = loadedStudents.filter(x => x.active);
      const moved = activeStudents.some(s => Math.abs(s.dx) > 1 || Math.abs(s.dy) > 1);
      if (moved) {
          document.getElementById('btn-save-offset').style.display = 'inline-block';
          document.getElementById('btn-cancel-offset').style.display = 'inline-block';
      }
  };
