function extractJson(raw) {
  let source = raw.trim();
  const codeBlock = source.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (codeBlock) {
    source = codeBlock[1].trim();
  } else {
    const start = Math.min(
      source.indexOf('{') === -1 ? Infinity : source.indexOf('{'),
