}

async function loadEditorForPage() {
  const page = getSelectedPageNum();
  const questions = globalRegions.questions.filter((q) => (q.page || 1) === page);
  document.getElementById('editor-container').style.display = 'block';
  document.getElementById('editor-save-status').textContent = '?섏씠吏 濡쒕뵫 以?..';

