    setStatus('editor-save-status', `${page}?섏씠吏 濡쒕뱶 ?꾨즺`, 'green');
  } catch (error) {
    setStatus('editor-save-status', error.message || '?섏씠吏 濡쒕뱶 ?ㅽ뙣', 'red');
  }
}

async function saveEditorForPage() {
  const liveQuestions = typeof editorGetQuestions === 'function' ? editorGetQuestions() : [];
  const page = getSelectedPageNum();
  liveQuestions.forEach((question) => {
    if (!question.page) question.page = page;
  });

  const others = globalRegions.questions.filter((q) => (q.page || 1) !== page);
  globalRegions.questions = [...others, ...liveQuestions];
  setStatus('editor-save-status', '???以?..', 'muted');

  const response = await fetch('/api/regions', {
    method: 'POST',
