    body: JSON.stringify(globalRegions),
  });
  if (response.ok) {
    setStatus('editor-save-status', `${page}?섏씠吏 ????꾨즺`, 'green');
    await loadFileStatus();
  } else {
    setStatus('editor-save-status', '????ㅽ뙣', 'red');
  }
}

async function runPipeline() {
  const templateCount = fileStatus.template.count || 1;
  let cycle = prompt('?숈깮 1紐낅떦 ?ㅼ틪???섏씠吏 ?섎? ?낅젰?섏꽭??', templateCount);
  if (cycle === null) return;
  cycle = parseInt(cycle, 10);
  if (Number.isNaN(cycle) || cycle < 1) {
    alert('?щ컮瑜??レ옄瑜??낅젰?섏꽭??');
    return;
  }

  const button = document.getElementById('pipeline-btn');
  button.disabled = true;
  setStatus('pipeline-status', '?뺣젹 ?ㅽ뻾 以?..', 'muted');

  try {
    const response = await fetch('/api/run_pipeline', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ cycle }),
