      );
      await loadFileStatus();
    } else {
      setStatus('pipeline-status', data.error || '?뺣젹 ?ㅽ뙣', 'red');
    }
  } catch (error) {
    setStatus('pipeline-status', '?쒕쾭 ?듭떊 ?ㅻ쪟', 'red');
  } finally {
    button.disabled = false;
  }
}

function setStatus(id, message, color) {
  const el = document.getElementById(id);
  if (!el) return;
  el.textContent = message;
  el.style.color = color === 'green' ? '#22c55e' : color === 'red' ? '#ef4444' : '#94a3b8';
}

