        if ext == ".pdf":
            with tempfile.TemporaryDirectory() as tmp_dir:
                tmp_pdf = Path(tmp_dir) / "template.pdf"
                with open(tmp_pdf, "wb") as target:
                    shutil.copyfileobj(file.file, target)
