    import cv2
    import numpy as np
    from aligner import _imread_safe, _imwrite_safe  # type: ignore

    paths = _paths()
    data = await request.json()
    name = data.get("name")
    dx = int(data.get("dx", 0))
    dy = int(data.get("dy", 0))
