    height, width = img.shape[:2]
    matrix = np.float32([[1, 0, dx], [0, 1, dy]])
    shifted = cv2.warpAffine(img, matrix, (width, height), borderValue=(255, 255, 255))
    _imwrite_safe(str(path), shifted)

